<?php
require __DIR__.'/config.php';$u=require_role('customer');$carId=(int)($_GET['car']??$_POST['car_id']??0);$q=db()->prepare('SELECT * FROM cars WHERE id=? AND available=1');$q->execute([$carId]);$car=$q->fetch();if(!$car){flash('That vehicle is not available.','danger');redirect('index.php');}
$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$start=$_POST['start_date']??'';$end=$_POST['end_date']??'';$payment=$_POST['payment_method']??'';$allowed=['Zaad','Sahal','EVC Plus','Credit / Debit Card','Pay on pickup'];
if(!$start||!$end||$end<=$start||$start<date('Y-m-d')||!in_array($payment,$allowed,true))$error='Please enter valid dates and choose a payment method.';
else{$pdo=db();$pdo->beginTransaction();try{$lock=$pdo->prepare('SELECT id,price_per_day,available FROM cars WHERE id=? FOR UPDATE');$lock->execute([$carId]);$locked=$lock->fetch();$over=$pdo->prepare("SELECT id FROM bookings WHERE car_id=? AND status IN ('Pending','Confirmed') AND start_date < ? AND end_date > ? LIMIT 1");$over->execute([$carId,$end,$start]);if(!$locked||!$locked['available']||$over->fetch()){$pdo->rollBack();$error='This car is already booked for some of those dates. Please choose another date.';}else{$days=booking_days($start,$end);$total=$days*(float)$locked['price_per_day'];$ins=$pdo->prepare("INSERT INTO bookings(user_id,car_id,start_date,end_date,days,total,payment_method,status) VALUES(?,?,?,?,?,?,?,'Pending')");$ins->execute([$u['id'],$carId,$start,$end,$days,$total,$payment]);$pdo->commit();flash('Your reservation was submitted and is awaiting confirmation.');redirect('dashboard.php#bookings');}}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}}}
$pageTitle='Reserve '.$car['name'];require __DIR__.'/partials/header.php';?>
<div class="row justify-content-center"><div class="col-lg-8"><div class="card border-0 shadow-sm"><img src="<?=h($car['image_url'])?>" class="card-img-top car-img" style="height:260px" alt="<?=h($car['name'])?>"><div class="card-body p-4"><h2 class="fw-bold"><?=h($car['name'])?></h2><p class="text-secondary"><?=h($car['description'])?></p><p class="price"><?=money($car['price_per_day'])?> <small class="fs-6 text-secondary fw-normal">per day</small></p><?php if($error):?><div class="alert alert-danger"><?=h($error)?></div><?php endif;?>
<form method="post" id="bookingForm"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="car_id" value="<?=$carId?>"><div class="row"><div class="col-md-6 mb-3"><label class="form-label">Pickup date</label><input id="pickupDate" class="form-control booking-date" type="date" name="start_date" min="<?=date('Y-m-d')?>" required></div><div class="col-md-6 mb-3"><label class="form-label">Return date</label><input id="returnDate" class="form-control booking-date" type="date" name="end_date" min="<?=date('Y-m-d',strtotime('+1 day'))?>" required></div></div><div class="mb-3"><label class="form-label text-dark">Payment method</label><select class="form-select" name="payment_method" required><option value="">Choose payment method</option><?php foreach(['Zaad','Sahal','EVC Plus','Credit / Debit Card','Pay on pickup'] as $p):?><option><?=h($p)?></option><?php endforeach;?></select></div><button class="btn btn-primary">Submit reservation</button><a href="index.php" class="btn btn-outline-secondary">Cancel</a></form></div></div></div></div>
